import { sql } from 'drizzle-orm';
import { check, sqliteTable, text } from 'drizzle-orm/sqlite-core';

export const projects = sqliteTable(
  'projects',
  {
    id: text().primaryKey(),
    name: text().notNull(),
    createdAt: text('created_at').notNull(),
    lastOpenedAt: text('last_opened_at').notNull(),
    storageKind: text('storage_kind', { enum: ['project', 'bundle'] })
      .notNull()
      .default('project'),
    sourceFingerprint: text('source_fingerprint'),
    removedAt: text('removed_at'),
    pinnedAt: text('pinned_at'),
  },
  (table) => [
    check(
      'projects_storage_kind',
      sql`${table.storageKind} IN ('project', 'bundle')`,
    ),
  ],
);

export const workspaces = sqliteTable('workspaces', {
  id: text().primaryKey(),
  projectId: text('project_id')
    .notNull()
    .unique()
    .references(() => projects.id),
  canonicalPath: text('canonical_path').notNull().unique(),
});

export const historyRoots = sqliteTable('history_roots', {
  canonicalPath: text('canonical_path').primaryKey(),
  projectId: text('project_id')
    .notNull()
    .references(() => projects.id),
});
